svg.script:
(function () {
  var hits = document.querySelectorAll(".sp-hit");
  if (!hits.length) { return; }

  function show(idx) {
    for (var i = 0; i < hits.length; i++) {
      if (i === idx) { hits[i].parentNode.classList.add("is-inview"); }
      else { hits[i].parentNode.classList.remove("is-inview"); }
    }
  }

  // Which slab is centred in the browser viewport cannot be worked out from in
  // here: this file is loaded cross-origin, so rootMargin is ignored on an
  // implicit IntersectionObserver root, and intersectionRect only exposes a
  // viewport edge when a slab is actually clipped by it. The page has to tell
  // us. It posts {spendly: 0|1|2} on scroll; see the Webflow snippet.
  var heard = false;
  window.addEventListener("message", function (e) {
    var d = e.data;
    if (!d || typeof d.spendly !== "number") { return; }
    heard = true;
    show(d.spendly);
  }, false);

  // Fallback when the page snippet is absent: reveal the middle slab only, and only
  // when this object is narrow enough to be in overlay mode. Without that guard a
  // missing snippet would pin a panel open on desktop, since the .is-inview rules
  // now live outside the breakpoint. Never reveal all three.
  setTimeout(function () {
    if (!heard && window.innerWidth <= 645) { show(1); }
  }, 600);
})();
